def compute(vars):
    count = 1
    if count == 0:
        return None

    average = vars["v1"] / count
    result = round(average)

    return {
        "value": result,
        "trace": {
            "values": [vars["v1"]],
            "count": count,
            "average": average,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
